from __future__ import annotations

import asyncio
from collections.abc import AsyncIterator
from typing import Generic, TypeVar

T = TypeVar("T")


class MultiCursorBuffer(Generic[T]):
    """An async buffer that can be iterated by many independent cursors.

    Every iterator created via `__aiter__` replays all items buffered so far
    from index zero and then suspends until new items are pushed. Items pushed
    after an iterator starts waiting are delivered to it. Closing the buffer
    releases all waiting iterators, which then terminate cleanly.
    """

    def __init__(self) -> None:
        self._items: list[T] = []
        self._closed = False
        # Futures for iterators currently suspended waiting for new items.
        self._wakeups: set[asyncio.Future[None]] = set()

    def push(self, item: T) -> None:
        """Append an item and wake any iterators waiting for new items."""
        self._items.append(item)
        self._notify()

    def close(self) -> None:
        """Signal that no further items will be pushed, releasing waiters."""
        self._closed = True
        self._notify()

    def _notify(self) -> None:
        wakeups, self._wakeups = self._wakeups, set()
        for future in wakeups:
            if not future.done():
                future.set_result(None)

    def __len__(self) -> int:
        return len(self._items)

    def __aiter__(self) -> AsyncIterator[T]:
        return self._iterate()

    async def _iterate(self) -> AsyncIterator[T]:
        index = 0
        while True:
            while index < len(self._items):
                yield self._items[index]
                index += 1
            if self._closed:
                return
            loop = asyncio.get_event_loop()
            future: asyncio.Future[None] = loop.create_future()
            self._wakeups.add(future)
            try:
                await future
            finally:
                self._wakeups.discard(future)
