    "messages": "messages",
    "tools": "tools",
    "lifecycle": "lifecycle",
    "tasks": "tasks",
    "input.requested": "input",
}


def normalize_segment(segment: str) -> str:
    """Strip the suffix starting at the first colon from a segment.

    Returns the segment unchanged when it contains no colon.
    """
    index = segment.find(":")
    if index == -1:
        return segment
    return segment[:index]


def is_prefix_match(namespace: list[str], prefix: list[str]) -> bool:
    """Return True if `namespace` starts with all segments in `prefix`.

    Each namespace segment is normalized (colon-suffix stripped) before being
    compared. A prefix segment that itself contains a colon is treated as an
    exact literal and compared against the raw namespace segment. An empty
    prefix matches any namespace; a prefix longer than the namespace never
    matches.
    """
    if len(prefix) > len(namespace):
        return False
    for ns_segment, prefix_segment in zip(namespace, prefix):
        if ":" in prefix_segment:
            if ns_segment != prefix_segment:
                return False
        elif normalize_segment(ns_segment) != prefix_segment:
            return False
    return True


def namespace_matches(
    namespace: list[str],
    prefixes: list[list[str]] | None,
    depth: int | None = None,
) -> bool:
    """Return True if `namespace` satisfies the prefix and depth constraints.

    A `None` or empty `prefixes` list matches any namespace. When `depth` is
    given, namespaces deeper than the limit never match. Otherwise the
    namespace matches when at least one prefix passes `is_prefix_match`.
    """
    if prefixes is None or len(prefixes) == 0:
        return True
    if depth is not None and len(namespace) > depth:
        return False
    return any(is_prefix_match(namespace, prefix) for prefix in prefixes)


def infer_channel(event: dict[str, Any]) -> str | None:
    """Map an event's `method` field to its channel name.

    Returns `None` for unknown methods. For the `custom` method the channel is
    `custom:{name}` when the event data carries a non-empty `name`, otherwise
    it is `custom`.
    """
    method = event.get("method")
    if method == "custom":
        data = event.get("data")
        name = data.get("name") if isinstance(data, dict) else None
        if name:
            return f"custom:{name}"
        return "custom"
    if method is None:
        return None
    return _METHOD_TO_CHANNEL.get(method)


def matches_subscription(event: dict[str, Any], subscription: dict[str, Any]) -> bool:
    """Return True if `event` matches the given `subscription`.

    The event's inferred channel must be listed in `subscription['channels']`.
    A bare `custom` entry matches any namespaced custom channel (e.g.
    `custom:my_ext`). When the subscription carries a `namespaces` filter, the
    event's namespace must also satisfy `namespace_matches`.
    """
    channel = infer_channel(event)
    if channel is None:
        return False

    channels = subscription.get("channels") or []
    if channel in channels:
        matched = True
    elif channel.startswith("custom:") and "custom" in channels:
        matched = True
    else:
        matched = False
    if not matched:
        return False

    if "namespaces" in subscription:
        namespace = event.get("namespace") or []
        if not namespace_matches(
            namespace, subscription.get("namespaces"), subscription.get("depth")
        ):
            return False

    return True
